from datetime import datetime

def get_next_yoga_class():
    # Get today's date
    today = get_current_day()

    # Search for yoga classes
    events = search_calendar_events(query="Yoga Class", date=today)

    if not events:
        # If no events are found, try searching for events without specifying a date
        events = search_calendar_events(query="Yoga Class", date=None)

    # Find the next yoga class
    next_yoga_class = None
    for event in events:
        if event.start_time > datetime.now():
            if next_yoga_class is None or event.start_time < next_yoga_class.start_time:
                next_yoga_class = event

    if next_yoga_class is None:
        raise ValueError("No upcoming yoga classes found")

    # Return the start time of the next yoga class in the format 'YYYY-MM-DD HH:MM'
    return next_yoga_class.start_time.strftime('%Y-%m-%d %H:%M')

print(get_next_yoga_class())
